from . import store


def on_save(doc, ctx):
    doc["saves"] += 1
    doc["text"] = doc["text"].rstrip() + "\n"
    return doc


def save(doc_id, text, ctx=None):
    doc = store.put(doc_id, text)
    if ctx is not None:
        ctx.append(("save", doc_id))
    return on_save(doc, ctx)


def autosave(doc_id, ctx=None):
    doc = store.get(doc_id)
    if doc is None:
        return None
    if ctx is not None:
        ctx.append(("autosave", doc_id))
    return on_save(doc, ctx)
_DOCS = {}


def put(doc_id, text):
    _DOCS[doc_id] = {"id": doc_id, "text": text, "saves": 0}
    return _DOCS[doc_id]


def get(doc_id):
    return _DOCS.get(doc_id)
from notes import hooks


def test_save_and_autosave():
    d = hooks.save("a", "hello  ")
    assert d["text"] == "hello\n" and d["saves"] == 1
    assert hooks.autosave("a")["saves"] == 2
    assert hooks.autosave("missing") is None
